{
  "candidates": [
    {
      "explanation": "Moderate demand surge response: increase orders at all nodes when recent demand exceeds baseline, with larger increase at node0 to buffer against pipeline delay. Node1 and node2 also increase to prevent stockouts downstream. Corrections are small and coordinated.",
      "rules": [
        {
          "when": "agent==0 and growth>1.1",
          "delta": "min(4, max(0, (recent-baseline)*2))"
        },
        {
          "when": "agent==1 and growth>1.1",
          "delta": "min(3, max(0, (recent-baseline)*1.5))"
        },
        {
          "when": "agent==2 and growth>1.1",
          "delta": "min(2, max(0, (recent-baseline)*1))"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand to avoid overstock, but increase if backlog exists. Node0 focuses on pipeline, node1 and node2 on backlog and pipeline.",
      "rules": [
        {
          "when": "agent==0 and pipeline>recent*2",
          "delta": "-min(3, max(0, (pipeline-recent*2)/2))"
        },
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(4, backlog)"
        },
        {
          "when": "agent==1 and pipeline>recent*2",
          "delta": "-min(2, max(0, (pipeline-recent*2)/2))"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(3, backlog)"
        }
      ]
    },
    {
      "explanation": "Coordinated surge with pipeline awareness: increase orders at all nodes when growth is high, but cap increases based on pipeline to avoid overordering. Node0 gets largest increase, node1 moderate, node2 smallest.",
      "rules": [
        {
          "when": "agent==0 and growth>1.2",
          "delta": "min(5, max(0, (recent-baseline)*2 + (backlog>0)*2))"
        },
        {
          "when": "agent==1 and growth>1.2",
          "delta": "min(4, max(0, (recent-baseline)*1.5 + (backlog>0)*1.5))"
        },
        {
          "when": "agent==2 and growth>1.2",
          "delta": "min(3, max(0, (recent-baseline)*1 + (backlog>0)*1))"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Pipeline-aware relaxation: reduce orders when pipeline is high relative to recent demand, increase when inventory is low and pipeline is low. Coordinated across nodes to avoid starvation.",
      "rules": [
        {
          "when": "pipeline > 3 * recent",
          "delta": "-2"
        },
        {
          "when": "inventory < 5 and pipeline < 2 * recent",
          "delta": "2"
        },
        {
          "when": "backlog > 0",
          "delta": "1"
        }
      ]
    },
    {
      "explanation": "Downstream service protection: boost orders at upstream nodes when downstream backlog exists or downstream inventory is low, while moderating orders at downstream nodes if their pipeline is excessive.",
      "rules": [
        {
          "when": "agent == 0 and backlog > 0",
          "delta": "2"
        },
        {
          "when": "agent == 1 and inventory < 10 and pipeline < 3 * recent",
          "delta": "2"
        },
        {
          "when": "agent == 2 and pipeline > 4 * recent",
          "delta": "-2"
        },
        {
          "when": "agent == 2 and inventory < 5",
          "delta": "1"
        }
      ]
    },
    {
      "explanation": "Emergency response: increase orders moderately at all nodes when recent demand exceeds baseline, but cap increases if pipeline is already high to prevent overreaction.",
      "rules": [
        {
          "when": "growth > 1.1 and pipeline < 3 * recent",
          "delta": "2"
        },
        {
          "when": "growth > 1.1 and pipeline >= 3 * recent",
          "delta": "1"
        },
        {
          "when": "growth < 0.9 and pipeline > 2 * recent",
          "delta": "-1"
        }
      ]
    }
  ]
}

{
  "candidates": [
    {
      "explanation": "Modest coordinated increase to replenish depleted inventories and reduce backlogs, with node0 ordering more to cover its large backlog and node1/2 slightly increasing to support downstream. Pipeline is healthy, so small increments avoid overshoot.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog/10)"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(4, backlog/5)"
        },
        {
          "when": "agent==2 and backlog>0",
          "delta": "min(4, backlog/5)"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    },
    {
      "explanation": "Pipeline-aware relaxation: when pipeline is high relative to recent demand, reduce orders to prevent excess inventory; when backlog is high, increase orders to clear it. Node0 focuses on backlog, node1/2 balance pipeline and backlog.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog/8)"
        },
        {
          "when": "agent==1 and pipeline>recent*3",
          "delta": "-2"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(4, backlog/4)"
        },
        {
          "when": "agent==2 and pipeline>recent*3",
          "delta": "-2"
        }
      ]
    },
    {
      "explanation": "Aggressive backlog clearance: increase orders proportionally to backlog at each node, capped to avoid excessive ordering. Node0 increases most due to largest backlog, node1 and node2 moderate increases.",
      "rules": [
        {
          "when": "agent==0 and backlog>0",
          "delta": "min(6, backlog/6)"
        },
        {
          "when": "agent==1 and backlog>0",
          "delta": "min(5, backlog/3)"
        },
        {
          "when": "agent==2 and backlog>0",
          "delta": "min(5, backlog/3)"
        },
        {
          "when": "true",
          "delta": "0"
        }
      ]
    }
  ]
}
